'use strict';
// Studio-only confirmed-payment inspection examples. Never inserted into account/payment state.
const paymentPreviewExamples=[
 {id:'preview-netflix-oct',recordId:'netflix-primary',name:'Netflix',cycle:'2026-10-27',paidDate:'2026-10-24',amount:15.99,currency:'USD',source:'Gmail receipt',inboxEmail:'alex@example.com',evidenceId:'gmail-receipt-netflix-oct'},
 {id:'preview-spotify-oct',recordId:'spotify',name:'Spotify',cycle:'2026-10-20',paidDate:'2026-10-20',amount:11.99,currency:'USD',source:'Gmail receipt',inboxEmail:'alex@example.com',evidenceId:'gmail-receipt-spotify-oct'},
 {id:'preview-icloud-sep',recordId:'icloud+',name:'iCloud+',cycle:'2026-09-30',paidDate:'2026-09-30',amount:2.99,currency:'USD',source:'Gmail receipt',inboxEmail:'alex@example.com',evidenceId:'gmail-receipt-icloud-sep'}
];
const paymentsView={query:'',year:'',month:'all',chartStart:6,inspectMonth:'10',recordId:'',recordName:'',detailOrigin:''};let paymentDialogTrigger=null;
function paymentReceiptHistory(){const actual=[...paymentRecords.entries()].map(([id,r])=>({...r,id}));return (actual.length?actual:paymentPreviewExamples).sort((a,b)=>b.paidDate.localeCompare(a.paidDate)||a.id.localeCompare(b.id));}
function paymentHistoryRows(){if(current==='Payments · empty')return [];return paymentReceiptHistory().filter(r=>!paymentsView.recordId||r.recordId===paymentsView.recordId);}
function paymentHistoryTotals(rows){const sums=new Map();for(const r of rows){const cents=Math.round(Number(r.amount)*100);if(!Number.isFinite(cents)||cents<0)continue;sums.set(r.currency,(sums.get(r.currency)||0)+cents);}return [...sums].map(([currency,cents])=>({currency,amount:(cents/100).toFixed(2)}));}
function paymentSourceLabel(source){return source==='Gmail receipt'?'Gmail receipt':source.toLowerCase().includes('receipt')?'Receipt confirmed':'Marked by you';}
function paymentMatchesQuery(r,query){return r.name.toLowerCase().includes(query.trim().toLowerCase());}
function paymentsEmpty(noMatches=false){return `<div class="payments-empty">${mascotView({expression:noMatches?'sad':'neutral',size:108})}<h3>${noMatches?'No payments found':'No confirmed payments yet'}</h3><p>${noMatches?'Try a different subscription name.':'Payments appear here when Gmail sync finds a matching successful-payment receipt.'}</p><button class="payments-empty-action" ${noMatches?'data-clear-payment-search':'data-go="List"'}>${noMatches?'Clear search':'View subscriptions'} <span aria-hidden="true">›</span></button></div>`;}
const paymentMonthNames=['January','February','March','April','May','June','July','August','September','October','November','December'];
function paymentsInPeriod(rows,year,month='all'){return rows.filter(r=>r.paidDate.slice(0,4)===year&&(month==='all'||r.paidDate.slice(5,7)===month));}
function paymentMonthlySeries(rows,year,currency){const cents=Array(12).fill(0);for(const r of rows){if(r.currency!==currency||r.paidDate.slice(0,4)!==year)continue;const index=Number(r.paidDate.slice(5,7))-1,value=Math.round(Number(r.amount)*100);if(index>=0&&index<12&&Number.isFinite(value)&&value>=0)cents[index]+=value;}return cents.map(n=>n/100);}
function paymentsPeriodLabel(){return (paymentsView.month==='all'?'':paymentMonthNames[Number(paymentsView.month)-1]+' ')+paymentsView.year;}
function paymentChartWindow(start){const first=start<6?0:6;return Array.from({length:6},(_,i)=>first+i);}
function paymentMiniChart(currency){const values=paymentMonthlySeries(paymentHistoryRows(),paymentsView.year,currency),indices=paymentChartWindow(paymentsView.chartStart),max=Math.max(...values,1),selected=Number(paymentsView.inspectMonth)-1;return `<section class="payment-wide-chart" aria-label="Monthly confirmed payments, ${escape(currency)}"><div class="payment-chart-toolbar"><span>${paymentMonthNames[indices[0]].slice(0,3)}–${paymentMonthNames[indices[5]].slice(0,3)} ${paymentsView.year}</span><div><button data-payment-chart-page="0" ${indices[0]===0?'disabled':''} aria-label="Previous six months">‹</button><button data-payment-chart-page="6" ${indices[0]===6?'disabled':''} aria-label="Next six months">›</button></div></div><p class="payment-chart-reading" role="status">${paymentMonthNames[selected]} · <strong>${escape(currency)} ${values[selected].toFixed(2)}</strong> confirmed</p><div class="payment-wide-bars" role="group" aria-label="Inspect a month without filtering the payment list">${indices.map(i=>{const month=String(i+1).padStart(2,'0'),amount=values[i];return `<button data-payment-inspect="${month}" data-chart-currency="${escape(currency)}" aria-pressed="${paymentsView.inspectMonth===month}" aria-label="${paymentMonthNames[i]} ${paymentsView.year}, ${escape(currency)} ${amount.toFixed(2)} confirmed. Inspect amount"><span class="payment-column-track"><span class="payment-column-fill" style="height:${amount?Math.max(5,Math.round(amount/max*60)):2}px"></span></span><span class="payment-column-label">${paymentMonthNames[i].slice(0,3)}</span></button>`;}).join('')}</div></section>`;}
function paymentsPeriodSummary(){const period=paymentsInPeriod(paymentHistoryRows(),paymentsView.year,paymentsView.month),currencies=[...new Set(paymentHistoryRows().map(r=>r.currency))],totals=paymentHistoryTotals(period);return `<section class="payments-summary"><div><span class="payments-summary-label">Confirmed payments</span><span class="payments-period">${paymentsPeriodLabel()}</span></div>${currencies.map(currency=>`<div class="payment-summary-metric"><strong><small>${escape(currency)}</small> ${totals.find(r=>r.currency===currency)?.amount||'0.00'}</strong></div>`).join('')}<p>${period.length} payment${period.length===1?'':'s'} · Scheduled charges aren’t included</p><div class="payment-charts-container">${currencies.map(paymentMiniChart).join('')}</div></section>`;}
function alignPaymentChart(){const month=paymentsView.month==='all'?(paymentsInPeriod(paymentHistoryRows(),paymentsView.year)[0]?.paidDate.slice(5,7)||'01'):paymentsView.month;paymentsView.inspectMonth=month;paymentsView.chartStart=Number(month)<=6?0:6;}
function paymentsResults(){const rows=paymentHistoryRows(),period=paymentsInPeriod(rows,paymentsView.year,paymentsView.month),matched=period.filter(r=>paymentMatchesQuery(r,paymentsView.query));if(!rows.length)return paymentsEmpty();if(!matched.length)return paymentsView.query?paymentsEmpty(true):`<div class="payments-empty payments-period-empty">${mascotView({expression:'neutral',size:96})}<h3>No payments this month</h3><p>No confirmed payments for ${paymentsPeriodLabel()}.</p><button class="payments-empty-action" data-payment-all-months>Show all months <span aria-hidden="true">›</span></button></div>`;return `<p class="payments-result-count" role="status">${matched.length} payment${matched.length===1?'':'s'}<span>Newest first</span></p><div class="rows payments-rows">${matched.map(r=>subscriptionRowShell(`data-payment-history-id="${escape(r.id)}" aria-label="View ${escape(r.name)} payment on ${detailDate(r.paidDate)}"`,`<span class="avatar">${platformLogo(r.name)}</span><span class="body"><strong>${escape(r.name)}</strong><small>${detailDate(r.paidDate)}</small><small class="payments-source">${escape(paymentSourceLabel(r.source))}</small></span><span class="amount">${escape(r.currency)} ${Number(r.amount).toFixed(2)}<small class="payments-confirmed">Confirmed</small></span><span class="payments-chevron" aria-hidden="true">›</span>`)).join('')}</div>`;}
function paymentsScreen(){const rows=paymentHistoryRows(),years=[...new Set(rows.map(r=>r.paidDate.slice(0,4)))].sort().reverse();if(rows.length&&!years.includes(paymentsView.year)){paymentsView.year=years.includes(calendarToday.slice(0,4))?calendarToday.slice(0,4):years[0];alignPaymentChart();}return `<section class="payments-screen"><div class="head">${backButton({attributes:`data-payments-back`,label:"Go back",className:""})}<h2>Payments</h2></div><p class="payments-intro">${paymentsView.recordId?escape(paymentsView.recordName)+' · ':''}Payment receipts found in Gmail.</p>${rows.length?`<div class="payments-period-controls">${selectField({label:'Year',name:'paymentYear',value:paymentsView.year,options:years})}${selectField({label:'Month',name:'paymentMonth',value:paymentsView.month,options:[{value:'all',label:'All months'},...paymentMonthNames.map((label,i)=>({value:String(i+1).padStart(2,'0'),label}))]})}</div><div class="payments-summary-container">${paymentsPeriodSummary()}</div><label class="payments-search">Search<input type="search" data-payments-search placeholder="Search payments" value="${escape(paymentsView.query)}"></label>`:''}<div class="payments-results">${paymentsResults()}</div></section>`;}
function refreshPaymentPeriod(){document.querySelector('.payments-summary-container').innerHTML=paymentsPeriodSummary();document.querySelector('.payments-results').innerHTML=paymentsResults();const month=document.querySelector('[name=paymentMonth]');if(month)month.value=paymentsView.month;syncSelectControls();}
document.addEventListener('change',e=>{if(e.target.name==='paymentYear'){paymentsView.year=e.target.value;alignPaymentChart();refreshPaymentPeriod();}else if(e.target.name==='paymentMonth'){paymentsView.month=e.target.value;alignPaymentChart();refreshPaymentPeriod();}});
document.addEventListener('click',e=>{const inspect=e.target.closest('[data-payment-inspect]'),page=e.target.closest('[data-payment-chart-page]'),all=e.target.closest('[data-payment-all-months]');if(inspect||page){if(inspect)paymentsView.inspectMonth=inspect.dataset.paymentInspect;else{paymentsView.chartStart=Number(page.dataset.paymentChartPage);paymentsView.inspectMonth=String(paymentsView.chartStart+1).padStart(2,'0');}const currencies=[...new Set(paymentHistoryRows().map(r=>r.currency))];document.querySelector('.payment-charts-container').innerHTML=currencies.map(paymentMiniChart).join('');const selector=inspect?'[data-payment-inspect="'+paymentsView.inspectMonth+'"]':'[data-payment-chart-page]:not([disabled])';document.querySelector(selector)?.focus();}else if(all){paymentsView.month='all';alignPaymentChart();refreshPaymentPeriod();document.querySelector('[name=paymentMonth]')?.parentElement.querySelector('[data-select-trigger]')?.focus();}});
function closePaymentHistoryDialog(){const overlay=document.querySelector('.payment-history-overlay');if(!overlay)return;const phone=overlay.closest('.phone');overlay.remove();phone.querySelectorAll('[data-payment-history-inert]').forEach(el=>{el.inert=false;el.removeAttribute('data-payment-history-inert');});paymentDialogTrigger?.focus();}
function openPaymentHistoryDialog(trigger){const r=paymentHistoryRows().find(r=>r.id===trigger.dataset.paymentHistoryId);if(!r)return;paymentDialogTrigger=trigger;const phone=trigger.closest('.phone'),overlay=document.createElement('div');overlay.className='payment-history-overlay';overlay.innerHTML=`<div class="payment-history-shade" data-close-payment-history></div><section class="payment-history-dialog" role="dialog" aria-modal="true" aria-labelledby="payment-history-title"><header><h3 id="payment-history-title">Payment details</h3><button data-close-payment-history aria-label="Close payment details">×</button></header><div class="payment-history-identity"><span class="avatar">${platformLogo(r.name)}</span><strong>${escape(r.name)}</strong><span class="payments-confirmed">Confirmed</span></div><div class="payment-history-amount">${escape(r.currency)} ${Number(r.amount).toFixed(2)}</div>${fr('Payment date',detailDate(r.paidDate))}${fr('Billing date',detailDate(r.cycle))}${fr('Evidence source',escape(paymentSourceLabel(r.source)))}${r.inboxEmail?fr('Receipt inbox',escape(r.inboxEmail)):''}<p class="payment-history-note">${r.source==='Gmail receipt'?'Matched to a successful-payment receipt from your connected inbox.':r.source.toLowerCase().includes('receipt')?'Previously reviewed and confirmed by you.':'Previously marked as paid by you.'} Confirmation doesn’t change your renewal schedule.</p><button class="secondary" data-payment-subscription="${escape(r.recordId)}">View subscription <span aria-hidden="true">›</span></button></section>`;for(const el of phone.children){if(!el.inert){el.inert=true;el.dataset.paymentHistoryInert='true';}}phone.append(overlay);overlay.querySelector('[data-close-payment-history]').focus();}
document.addEventListener('input',e=>{if(!e.target.matches('[data-payments-search]'))return;paymentsView.query=e.target.value;document.querySelector('.payments-results').innerHTML=paymentsResults();});
document.addEventListener('click',e=>{const row=e.target.closest('[data-payment-history-id]'),close=e.target.closest('[data-close-payment-history]'),clear=e.target.closest('[data-clear-payment-search]'),sub=e.target.closest('[data-payment-subscription]');if(row)openPaymentHistoryDialog(row);else if(close)closePaymentHistoryDialog();else if(clear){paymentsView.query='';const field=document.querySelector('[data-payments-search]');if(field)field.value='';document.querySelector('.payments-results').innerHTML=paymentsResults();field?.focus();}else if(sub){const r=allTrackedRecords().find(r=>r.id===sub.dataset.paymentSubscription);if(!r){toast('This subscription is no longer available. Your payment record is kept.');return;}closePaymentHistoryDialog();state.manual={...r};demoName=r.name;demoPrice=r.price;go('Detail');}});
document.addEventListener('keydown',e=>{const overlay=document.querySelector('.payment-history-overlay');if(!overlay)return;if(e.key==='Escape'){e.preventDefault();closePaymentHistoryDialog();}else if(e.key==='Tab'){const controls=[...overlay.querySelectorAll('button')],first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});

document.addEventListener('click',e=>{if(e.target.closest('[data-payments-back]'))go(paymentsView.recordId?(paymentsView.detailOrigin||'Detail'):'Profile');});
